/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class responsible for populating the TMS engine TO temp table (calculation table)
/// </summary>
abstract class METTMSEngineTOLinesTmpBuilder
{
    METTMSEngineTransferOrderProccessLinesTmp   processLinesTmp;
    InventTransferTable                         transferTable;
    METInventTransferTableExt                   metTransferTable;
    SalesTable                                  salesTable;
    InventLocation                              inventLocation;
    METInventLocation                           metInventLocation;
    METInventLocation                           metInventLocationTo;
    InventParameters                            inventParameters;
    METTobaccoRepackQty                         tobaccoRepackQtyFactor;
    METTobaccoRepackQty                         standardRepackQtyFactor;
    TMSCarrierCode                              carrierCode;
    boolean                                     isOrderPerishable;
    boolean                                     isToteCustomer;
    InventLocationId                            prevInventLocationId;
    boolean                                     hasCCR;

    boolean                 isSalesOrderPerishable;


}

