/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_transferLine">Transfer order line</param>
/// <returns>Transfer order quantity</returns>
abstract protected InventTransferQty lineShipQty(InventTransferLine _transferLine)
{

}

/// <summary>
/// Get the warehouse id, custom secondaryInventLocationId if populated or std InventLocationId
/// </summary>
/// <param name = "_transferLine">Transfer order line</param>
/// <returns>Warehouse id</returns>
protected InventLocationId getInventLocationId(InventTransferLine _transferLine)
{
    METInventTransferLine       metTransferLine;// = METInventTransferLine::find(_transferLine.RecId);

    select firstonly metTransferLine
        where metTransferLine.InventTransferLine == _transferLine.RecId;

    //return metTransferLine.SecondaryInventLocationId ? metSalesLine.SecondaryInventLocationId : _transferLine.inventDim().InventLocationId;

    return _transferLine.inventDim().InventLocationId;
}

/// <summary>
/// As common rule CCR is no except for METTMSEngineLinesTmpBuilder_PackingSlip
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Yes if supplier warehouse has CCR; otherwise, false.</returns>
protected NoYes setSuppWhsHasCCR(InventTransferLine _transferLine)
{
    // For CB624, CCR flag always set to No
    return NoYes::No;
}

/// <summary>
/// Constructs a new TMS engine lines temp builder.
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineTransferOrderProcess</param>
/// <param name = "_transferTable">Sales order header record</param>
/// <param name = "_shipmentId">SO finalisation shipment id</param>
/// <param name = "_wmsPicklistNumber">AIS WMS picking list number</param>
/// <returns>An instance of <c>METTMSEngineTOLinesTmpBuilder</c></returns>
public static METTMSEngineTOLinesTmpBuilder construct(METTMSEngineTransferOrderProcess _tmsEngineProcess, InventTransferTable _transferTable, METShipmentId _shipmentId = "", METWMSPicklistNumber _wmsPicklistNumber = "")
{
    METTMSEngineTOLinesTmpBuilder result;
    boolean error = false;

    switch (_tmsEngineProcess)
    {
        case (METTMSEngineTransferOrderProcess::Cancellation) :
        case (METTMSEngineTransferOrderProcess::Creation) :
            result = new METTMSEngineTOLinesTmpBuilder_Creation(_transferTable);                
            break;

        default:
            error = true;
            break;
    }

    if (error)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return result;
}

/// <summary>
/// Similar to what we had in METTMSEngineSalesOrderProccess\initTmpTable
/// </summary>
/// <returns>Temp table with all records inserted</returns>
public METTMSEngineTransferOrderProccessLinesTmp populateTmpTable()
{
    QueryRun qr = new QueryRun(this.initQuery());

    while (qr.next())
    {
        this.createTempTableRecords(qr);
    }

    return processLinesTmp;
}

/// <summary>
/// Get the hasCCR parameter
/// </summary>
/// <returns>true if at least one record CCR; otherwise, false.</returns>
public boolean hasCCR()
{
    return hasCCR;
}

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init(InventTransferTable _transferTable)
{
    transferTable           = _transferTable;
    metTransferTable        = transferTable.metInventTransferTableExt();
    inventParameters        = InventParameters::find();
    carrierCode             = TMSInventTransferTable::find(transferTable.TransferId).CarrierCode;
    isOrderPerishable       = METTMSEngineTransferOrderProccess::IsOrderPerishable(metTransferTable);
    //metInventLocationFrom   = METInventLocation::findByInventLocationId(transferTable.InventLocationIdFrom);
    metInventLocationTo     = METInventLocation::findByInventLocationId(transferTable.InventLocationIdTo);

    isToteCustomer          = CustTable::METIsToteCustomer(metInventLocationTo.InternalCustomer, metInventLocationTo.DataAreaId);

}

/// <summary>
/// initialize default parameters based on the line WH
/// </summary>
/// <param name = "_transferLine"><c>InventTransferLine</c> record</param>
protected void initTransferLineVariables(InventTransferLine _transferLine)
{
    InventLocationId inventLocationId = this.getInventLocationId(_transferLine);

    // to avoid resetting variables if the WH hasn't change
    if (inventLocationId != prevInventLocationId)
    {
        inventLocation          = InventLocation::find(inventLocationId);
        //metInventLocation       = METInventLocation::findByInventLocationId(inventLocationId);

        // Added as never initialized
        /*whsPalletVolume = METInventLocation.WHSPalletVolume;
        whsPalletWeight = METInventLocation.WHSPalletWeight;

        this.initValuesFromContainerType(inventParameters, inventLocationId);*/

        this.initRepackQtyFactor(transferTable, inventParameters, isToteCustomer, inventLocationId);

        prevInventLocationId = inventLocationId;
    }
}

