/// <summary>
/// init tobaccoRepackQtyFactor and standardRepackQtyFactor
/// </summary>
/// <param name = "_transferTable">Transfer order header record</param>
/// <param name = "_inventParameters">Inventory parameters record</param>
/// <param name = "_isToteCustomer">Is customer a Tote customer</param>
/// <param name = "_inventLocationId">Standard warehouse field or custom supplying warehouse from sales order line</param>
protected void initRepackQtyFactor(InventTransferTable _transferTable, InventParameters _inventParameters, boolean _isToteCustomer, InventLocationId _inventLocationId)
{
    METContainerTypeTable   containerTypeTable;

    //default values when no containerTypeTable
    tobaccoRepackQtyFactor = METConstants::tobaccoRepackQtyFactorDefault;
    standardRepackQtyFactor = METConstants::standardRepackQtyFactorDefault;

    //SalesTable  salesTableLoc   = _transferTable.metInventTransferTableExt().SalesId;

    if (CustTable::METHasToteAttributeType(metInventLocationTo.InternalCustomer, metInventLocationTo.DataAreaId))
    {
        // Tote customer search for Plastic (tote) container ID else Cardboard container ID
        WHSContainerTypeCode containerTypeCode = _isToteCustomer ? _inventParameters.METPlasticContainerID : _inventParameters.METCardboardContainerID;

        containerTypeTable   = METContainerTypeTable::find(containerTypeCode, _inventLocationId);
        if (containerTypeTable)
        {
            tobaccoRepackQtyFactor  = containerTypeTable.TobaccoRepackQty;
            standardRepackQtyFactor = containerTypeTable.GroceryRepackQty;
        }
    }
    // only when the customer doesn't have "Tote type" attribute type set repack qty to 1
    else
    {
        tobaccoRepackQtyFactor = 1;
        standardRepackQtyFactor = 1;
    }
}

/// <summary>
/// Initialise the sales order line query
/// </summary>
/// <returns><c>Query</c> object</returns>
protected Query initQuery()
{
    Query query = new Query();
    QueryBuildDataSource qbds = query.addDataSource(tableNum(InventTransferLine));

    qbds.addRange(fieldNum(InventTransferLine, TransferId)).value(queryValue(transferTable.TransferId));
    // Exclude canceled lines
    //qbds.addRange(fieldNum(InventTransferLine, )).value(SysQuery::valueNot(SalesStatus::Canceled));
    //qbds.addRange(fieldNum(SalesLine, Blocked)).value(queryValue(NoYes::No));

    return query;
}

/// <summary>
/// Method to create the METTMSEngineTransferOrderProccessLinesTmp records from the QueryRun
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object</param>
protected void createTempTableRecords(QueryRun _queryRun)
{
    InventTransferLine   transferLine;

    transferLine = this.getTablesQueryRun(_queryRun);

    // initialise all variables coming from the sales order line warehouse or supplying warehouse
    this.initTransferLineVariables(transferLine);

    this.createLineTmp(transferLine);
}

/// <summary>
/// Get tables from _queryRun object used to fill the temp table
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object used to fill the temp table</param>
/// <returns>Container of records from the <c>QueryRun</c> object</returns>
protected InventTransferLine getTablesQueryRun(QueryRun _queryRun)
{
    return _queryRun.get(tableNum(InventTransferLine));
}

/// <summary>
/// Method to initialise the METTMSEngineTransferOrderProccessLinesTmp temp record from transfer line
/// </summary>
/// <param name = "_transferLine">Transfer order line</param>
protected void createLineTmp(InventTransferLine _transferLine)
{
    METInventItemOrderSetup metInventItemOrderSetup;
    METSalesTable           metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId);

    processLinesTmp.clear();        

    processLinesTmp.ItemId      = _transferLine.ItemId;
    processLinesTmp.TransferId  = _transferLine.TransferId;
    processLinesTmp.SalesUnit   = InventTable::find(_transferLine.ItemId).salesUnitId();
    processLinesTmp.SalesQty    = this.lineShipQty(_transferLine);
    //if the Sale line’s Item Type = Inventory & Warehouse Management Parameters’ “Tobacco Metcash item type” set IsTobaccoItem = Yes
    select firstonly ItemType, FilterCode from metInventItemOrderSetup
        // CB626_TMSEngineSOPackingSlip
        // use the Line_SupplyWarehouse variable instead
            //where  metInventItemOrderSetup.SiteId == _salesLine.inventDim().InventSiteId
            where  metInventItemOrderSetup.SiteId == inventLocation.InventSiteId
                && metInventItemOrderSetup.ItemId == _transferLine.ItemId;

    //METTobaccoItemType should not be blank
    processLinesTmp.IsTobaccoItem = (metInventItemOrderSetup.ItemType == inventParameters.METTobaccoItemType && inventParameters.METTobaccoItemType != '') ? NoYes::Yes : NoYes::No;

    processLinesTmp.IsKegItem      = this.isKegItem(processLinesTmp.ItemId);
    processLinesTmp.LineCommodity  = this.getLineCommodity(processLinesTmp.IsTobaccoItem, metInventItemOrderSetup.FilterCode, metTransferTable.OrderSplitGroup);
    processLinesTmp.CaseQty_CaseLines  = (processLinesTmp.IsKegItem == NoYes::No && processLinesTmp.IsTobaccoItem == NoYes::No && processLinesTmp.SalesUnit != METConstants::unitEach) ? processLinesTmp.SalesQty : 0;
    processLinesTmp.BrokenCasesCountSecurity = processLinesTmp.IsTobaccoItem == NoYes::Yes ? processLinesTmp.SalesQty : 0;
    processLinesTmp.BrokenCasesCountNonSecurity = (processLinesTmp.IsKegItem == NoYes::No && processLinesTmp.IsTobaccoItem == NoYes::No && processLinesTmp.SalesUnit == METConstants::unitEach) ? processLinesTmp.SalesQty : 0;

    // CB626_TMSEngineSOPackingSlip
    processLinesTmp.Line_SupplyWhs = inventLocation.InventLocationId;
    processLinesTmp.SuppWhsHasCCR = this.setSuppWhsHasCCR(_transferLine);

    // CB626_TMSEngineSOPackingSlip new calc
    if (processLinesTmp.SuppWhsHasCCR)
    {
        processLinesTmp.RepackCountSecurity = 0;
        processLinesTmp.RepackCountNonSecurity = 0;
    }
    else
    {
        // CB624 previous calc
        processLinesTmp.RepackCountSecurity = tobaccoRepackQtyFactor ? processLinesTmp.BrokenCasesCountSecurity/tobaccoRepackQtyFactor : 0;
        processLinesTmp.RepackCountNonSecurity = standardRepackQtyFactor ? processLinesTmp.BrokenCasesCountNonSecurity/standardRepackQtyFactor : 0;
    }
    processLinesTmp.KegQtyUOM      = this.getKegQtyUOM(_transferLine.ItemId);

    // CB626_TMSEngineSOPackingSlip
    // Init inventDim variable based on the line WH instead of using salesLine.inventDim()
    // The order line could have a SecondaryInventLocationId configured for CSD or xDock
    InventDim inventDim;
    inventDim.InventLocationId = inventLocation.InventLocationId;
    inventDim.InventSiteId = inventLocation.InventSiteId;

    [processLinesTmp.LineUnitVolume, processLinesTmp.LineUnitWeight] = this.getLineUnitVolumeWeight(_transferLine.ItemId, /*_salesLine.inventDim()*/inventDim, InventTable::find(_transferLine.ItemId).salesUnitId());

    processLinesTmp.LineVolume_CaseLines  = processLinesTmp.CaseQty_CaseLines * processLinesTmp.LineUnitVolume;
    processLinesTmp.LineVolume_BrokenCaseSecurity = processLinesTmp.BrokenCasesCountSecurity * processLinesTmp.LineUnitVolume;
    processLinesTmp.LineVolume_BrokenCaseNonSecurity = processLinesTmp.BrokenCasesCountNonSecurity * processLinesTmp.LineUnitVolume;
    processLinesTmp.LineVolume_Kegs = processLinesTmp.IsKegItem ? processLinesTmp.SalesQty * processLinesTmp.LineUnitVolume : 0;

    processLinesTmp.LineWeight_BrokenCaseNonSecurity = processLinesTmp.BrokenCasesCountNonSecurity * processLinesTmp.LineUnitWeight;
    processLinesTmp.LineWeight_BrokenCaseSecurity = processLinesTmp.BrokenCasesCountSecurity * processLinesTmp.LineUnitWeight;
    processLinesTmp.LineWeight_CaseLines = processLinesTmp.CaseQty_CaseLines * processLinesTmp.LineUnitWeight;
    processLinesTmp.LineWeight_Kegs = processLinesTmp.IsKegItem ? processLinesTmp.SalesQty * processLinesTmp.LineUnitWeight : 0;     

    processLinesTmp.insert();
}

/// <summary>
/// If the item on the sales line has a Product attribute listed in the new setup table, set IsKegItem = Yes
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns><c>boolean</c> object</returns>
protected boolean isKegItem(ItemId    _itemId)
{
    EcoResProductInstanceValue      ecoResProductInstanceValue;
    METAttributeIdentifiers         attributeIdentifiers;
    InventTable                     inventTable;
    RetailEcoResInstanceAttributeValuesView attributeValuesTable;

    select firstonly crosscompany RecId from inventTable
        where inventTable.ItemId == _itemId
        join  RecId from ecoResProductInstanceValue
        where   ecoResProductInstanceValue.Product == inventTable.Product
        join InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == ecoResProductInstanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeValueText == attributeValuesTable.TextValue
                    &&  attributeIdentifiers.AttributeValueText != ''
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Product
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::Keg;

    return inventTable.RecId;
}

/// <summary>
/// get line commodity value
/// </summary>
/// <param name = "_isTobaccoItem">isTobaccoItem</param>
/// <param name = "_filterNum">WHSFilterNum</param>
/// <param name = "_orderSplitGroup">Order split group</param>
/// <returns><c>METTMSCommodity</c> object</returns>
protected METTMSCommodity getLineCommodity(boolean _isTobaccoItem, WHSFilterNum _filterNum, METOrderSplitGroup _orderSplitGroup)
{
    METTMSCommodity ret;

    if (_IsTobaccoItem)
    {
        return METConstants::tobCommodity;
    }
    else if (metInventLocation.SplitPerishableItems)
    {
        ret = (select WHSFilters where WHSFilters.FilterNum == _filterNum).METTMSCommodity;
    }
    if (!ret)
    {
        ret = MetSplitGroupTable::find(_orderSplitGroup).TMSCommodity;
    }

    return ret;
}

/// <summary>
/// get KegQtyUOM
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <returns><c>string value</c> object</returns>
protected str getKegQtyUOM(ItemId _itemId)
{
    str kegQtyUOM;
    METInventTable  metInventTable;

    select firstonly BottleSize from metInventTable
        where metInventTable.ItemId == _itemId;
    if (metInventTable.BottleSize)
    {
        kegQtyUOM   = strFmt('%1', metInventTable.BottleSize);
        //kegQtyUOM   = strFmt('@MET:KegQtyUOM',strRem(kegQtyUOM, '.'));
        kegQtyUOM   = strFmt('K%1',strRem(kegQtyUOM, '.'));
    }

    return kegQtyUOM;
}

/// <summary>
/// get LineUnitVolume and LineUnitWeight
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventDim">InventDim</param>
/// <param name = "_uom">WHSUOM</param>
/// <returns><c>container</c> object</returns>
protected container getLineUnitVolumeWeight(ItemId    _itemId,
                                            InventDim _inventDim,
                                            WHSUOM    _uom)
{
    METWHSPhysDimUOMSite    metWHSPhysDimUOMSite;
    WHSPhysDimUOM           whsPhysDimUOM;
    METUOMVolume            volume;
    Weight                  weight;
    WHSUOM                  warehouseUnit;

    select firstonly * from metWHSPhysDimUOMSite
        where metWHSPhysDimUOMSite.ItemId == _itemId
        && metWHSPhysDimUOMSite.UOM == _uom
        && metWHSPhysDimUOMSite.SiteId == _inventDim.InventSiteId;

    volume  = metWHSPhysDimUOMSite.displayVolume();
    weight  = metWHSPhysDimUOMSite.Weight;

    if (!volume || !weight)
    {
        warehouseUnit   = METInventLocation::getWarehouseUnit(_itemId, _inventDim);

        select firstonly * from whsPhysDimUOM
            where whsPhysDimUOM.ItemId == _itemId
            && whsPhysDimUOM.UOM == warehouseUnit;

        volume  = volume ? volume : whsPhysDimUOM.metDisplayVolume();
        weight  = weight ? weight : metWHSPhysDimUOMSite.Weight;
    }

    return [volume, weight];
}
